def check(inputs, outputs):
    res = []
    try:
        t = outputs.get('equilibrium temperature in K')
        if not isinstance(t, (int, float)) or isinstance(t, bool) or t != t:
            return res
        if t <= 0:
            res.append('equilibrium temperature %s K not positive' % t)
        def tk(text):
            if not isinstance(text, str):
                return None
            v = number(text)
            if v is None:
                return None
            s = text.replace(' ', '')
            if '\u00b0F' in s or s.endswith('F'):
                return (v - 32.0) * 5.0 / 9.0 + 273.15
            if '\u00b0C' in s or s.endswith('C'):
                return v + 273.15
            if s.endswith('K') or s.endswith('k'):
                return v
            return None
        a = None
        b = None
        for k, v in inputs.items():
            if 'initial temperature of the water' in k:
                a = tk(v)
            elif 'initial temperature of the aluminum' in k:
                b = tk(v)
        if a is not None and b is not None:
            lo = min(a, b)
            hi = max(a, b)
            tol = 0.01 + 1e-6 * abs(hi) + 0.001 * abs(hi)
            if t < lo - tol or t > hi + tol:
                res.append('equilibrium %s K outside initial temperatures %s K and %s K' % (t, lo, hi))
    except Exception:
        pass
    return res
